module tb_TopModule;
    reg       in;
    reg [1:0] state;
    wire [1:0] next_state;
    wire       out;

    TopModule uut (
        .in(in),
        .state(state),
        .next_state(next_state),
        .out(out)
    );

    initial begin
        // Test state A (2'b00)
        state = 2'b00;
        in = 0; #10;
        if (next_state !== 2'b00 || out !== 1'b0) $display("FAIL: A, in=0 -> next=%b out=%b", next_state, out);

        in = 1; #10;
        if (next_state !== 2'b01 || out !== 1'b0) $display("FAIL: A, in=1 -> next=%b out=%b", next_state, out);

        // Test state B (2'b01)
        state = 2'b01;
        in = 0; #10;
        if (next_state !== 2'b10 || out !== 1'b0) $display("FAIL: B, in=0 -> next=%b out=%b", next_state, out);

        in = 1; #10;
        if (next_state !== 2'b01 || out !== 1'b0) $display("FAIL: B, in=1 -> next=%b out=%b", next_state, out);

        // Test state C (2'b10)
        state = 2'b10;
        in = 0; #10;
        if (next_state !== 2'b00 || out !== 1'b0) $display("FAIL: C, in=0 -> next=%b out=%b", next_state, out);

        in = 1; #10;
        if (next_state !== 2'b11 || out !== 1'b0) $display("FAIL: C, in=1 -> next=%b out=%b", next_state, out);

        // Test state D (2'b11)
        state = 2'b11;
        in = 0; #10;
        if (next_state !== 2'b10 || out !== 1'b1) $display("FAIL: D, in=0 -> next=%b out=%b", next_state, out);

        in = 1; #10;
        if (next_state !== 2'b01 || out !== 1'b1) $display("FAIL: D, in=1 -> next=%b out=%b", next_state, out);

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
